using Bridge.Contracts;
using Xunit;

namespace Bridge.Contracts.Tests;

/// <summary>
/// Golden vectors from tests/golden-vectors.json (generated by
/// generate_golden_vectors.py and verified against contract_lab's own
/// _validate_envelope). Constants are copied here so the test is
/// self-contained; regenerate both sides together if the rule changes.
/// </summary>
public sealed class GoldenVectorTests
{
    private const string ClickJson =
        """{"schema_version": "1.0", "command_id": "11d497af-51d1-48ec-a5ab-c878e3cd6b4e", "device_id": "test-device", "lease_id": "523fe7e5-6ba0-4d6b-a662-e2cebe25f687", "epoch": 3, "sequence": 1, "operation": "input.click", "observation_id": "81c2158c-0af9-4e4d-aa04-f7a742989f59", "issued_at": "2026-11-13T12:00:00Z", "expires_at": "2026-11-13T12:00:15Z", "payload": {"x": 320, "y": 180}}""";

    [Fact]
    public void ClickDigestMatchesPython()
    {
        Assert.Equal(
            "8c6337c64836b0702b7397213949469930e88253300a0f5d7d0ceda1c312eff0",
            EnvelopeDigest.DigestEnvelope(ClickJson));
    }

    [Fact]
    public void TypeTextDigestMatchesPythonWithChineseAndEmoji()
    {
        const string json =
            """{"schema_version": "1.0", "command_id": "22d497af-51d1-48ec-a5ab-c878e3cd6b4e", "device_id": "test-device", "lease_id": "523fe7e5-6ba0-4d6b-a662-e2cebe25f687", "epoch": 3, "sequence": 2, "operation": "input.type_text", "observation_id": "81c2158c-0af9-4e4d-aa04-f7a742989f59", "issued_at": "2026-11-13T12:00:00Z", "expires_at": "2026-11-13T12:00:15Z", "payload": {"text": "你好，Windows 👋\n换行"}}""";
        Assert.Equal(
            "b707b72743e8f5dfa25d160043806f48f45252bbe6d308cd41be6bbcbed7dfa5",
            EnvelopeDigest.DigestEnvelope(json));
    }

    [Fact]
    public void KeyDigestMatchesPython()
    {
        const string json =
            """{"schema_version": "1.0", "command_id": "33d497af-51d1-48ec-a5ab-c878e3cd6b4e", "device_id": "test-device", "lease_id": "523fe7e5-6ba0-4d6b-a662-e2cebe25f687", "epoch": 3, "sequence": 3, "operation": "input.key", "observation_id": "81c2158c-0af9-4e4d-aa04-f7a742989f59", "issued_at": "2026-11-13T12:00:00Z", "expires_at": "2026-11-13T12:00:15Z", "payload": {"keys": ["CTRL", "C"]}}""";
        Assert.Equal(
            "02ade9396e5b3850153264da935603b42663e826cd1010e01996a58d4aad9651",
            EnvelopeDigest.DigestEnvelope(json));
    }

    [Fact]
    public void CanonicalJsonSortsKeysAndOmitsSpaces()
    {
        const string shuffled =
            """{"payload": {"y": 180, "x": 320}, "operation": "input.click"}""";
        Assert.Equal(
            """{"operation":"input.click","payload":{"x":320,"y":180}}""",
            EnvelopeDigest.CanonicalJson(System.Text.Json.JsonDocument.Parse(shuffled).RootElement));
    }
}
